    return sum(numbers) / len(numbers)

def count_up(n):
    """Return [1, 2, ..., n]."""
    return list(range(1, n + 1))

def starts_with_vowel(word):
    """Return True when *word* starts with a, e, i, o or u, ignoring case."""
    return word[:1].lower() in 'aeiou'

def percentage(part, whole):
    """Return part as a percentage of whole, or 0.0 when whole is 0."""
    if whole == 0:
        return 0.0
    return part / whole * 100

def last_element(items):
    """Return the last element, or None when the list is empty."""
    return items[-1] if items else None

def find_index(items, target):
    """Return the index of the first occurrence of *target*, or -1."""
    for i, item in enumerate(items):
        if item == target:
            return i
    return -1

def dedupe(items):
    """Remove duplicates, keeping the first occurrence of each value in order."""
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def clamp_value(value, low, high):
    """Return *value* limited to [low, high]."""
    return max(low, min(value, high))

def count_matches(items, predicate_value):
    """Count how many elements equal *predicate_value*."""
    total = 0
    for item in items:
        if item == predicate_value:
            total += 1
    return total

def chunk_list(items, size):
    """Split *items* into lists of at most *size* elements."""
    return [items[i:i + size] for i in range(0, len(items), size)]

def strip_prefix(text, prefix):
    """Remove *prefix* from the start of *text* if it is there, otherwise return *text*."""
    return text[len(prefix):] if text.startswith(prefix) else text

def sum_positive(numbers):
    """Add up every number greater than 0, skipping the rest."""
    total = 0
    for x in numbers:
        if x <= 0:
            continue
        total += x
    return total

def is_sorted(numbers):
    """Return True when *numbers* is non-decreasing."""
    for i in range(len(numbers) - 1):
        if numbers[i] > numbers[i + 1]:
            return False
    return True

def word_lengths(text):
    """Return the length of every word, ignoring leading and trailing . , ! and ?"""
    return [len(w.strip('.,!?')) for w in text.split()]
